-- Restaurant Journal: initial schema.
-- Households of up to two adults share places, visits and photos.
-- Every table is protected by row level security keyed on household membership.

-- ---------- Tables ----------

create table public.households (
  id uuid primary key default gen_random_uuid(),
  -- Invite code shown to the household, e.g. 3F9A-C21B-7D04. Generated by create_household().
  code text not null unique,
  created_at timestamptz not null default now()
);

create table public.members (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  user_id uuid not null unique references auth.users (id) on delete cascade,
  slot smallint not null check (slot in (1, 2)),
  display_name text not null check (char_length(display_name) between 1 and 30),
  created_at timestamptz not null default now(),
  unique (household_id, slot),
  unique (id, household_id)
);

create table public.places (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  status text not null check (status in ('want', 'been')),
  cuisine text check (cuisine in ('american','mexican','italian','asian','seafood','latin','bbq','breakfast','cafe','other')),
  found_note text check (char_length(found_note) <= 280),
  created_at timestamptz not null default now(),
  unique (id, household_id)
);
create index places_household_idx on public.places (household_id);

create table public.visits (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null,
  place_id uuid not null,
  logged_by uuid,
  date date not null,
  thumb text not null check (thumb in ('up', 'down')),
  -- {"wait":1-3,"space":1-3,"noiseAir":1-3,"service":1-3,"seating":1-3}, any subset
  ratings jsonb not null default '{}'::jsonb,
  note text check (char_length(note) <= 280),
  kid_ages text[] not null default '{}' check (kid_ages <@ array['newborn','toddler','preschool','schoolAge']),
  -- {"<member id>": "yes" | "no"}
  votes jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (id, household_id),
  -- A visit can only point at a place and a member in its own household.
  foreign key (place_id, household_id) references public.places (id, household_id) on delete cascade,
  foreign key (logged_by, household_id) references public.members (id, household_id) on delete set null (logged_by)
);
create index visits_household_idx on public.visits (household_id);
create index visits_place_idx on public.visits (place_id);

create table public.photos (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null,
  visit_id uuid not null,
  -- Object path in the private "photos" bucket: <household_id>/<photo id>.jpg
  storage_path text not null,
  width integer not null check (width > 0),
  height integer not null check (height > 0),
  created_at timestamptz not null default now(),
  foreign key (visit_id, household_id) references public.visits (id, household_id) on delete cascade
);
create index photos_household_idx on public.photos (household_id);
create index photos_visit_idx on public.photos (visit_id);

-- ---------- Membership helper ----------

create function public.is_household_member(hid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.members m
    where m.household_id = hid and m.user_id = (select auth.uid())
  );
$$;
revoke execute on function public.is_household_member(uuid) from public, anon;
grant execute on function public.is_household_member(uuid) to authenticated;

-- ---------- Row level security ----------

alter table public.households enable row level security;
alter table public.members enable row level security;
alter table public.places enable row level security;
alter table public.visits enable row level security;
alter table public.photos enable row level security;

create policy "members read their household" on public.households
  for select to authenticated using (public.is_household_member(id));

create policy "members read their household's members" on public.members
  for select to authenticated using (public.is_household_member(household_id));
create policy "members rename within their household" on public.members
  for update to authenticated
  using (public.is_household_member(household_id))
  with check (public.is_household_member(household_id));

create policy "household places" on public.places
  for all to authenticated
  using (public.is_household_member(household_id))
  with check (public.is_household_member(household_id));
create policy "household visits" on public.visits
  for all to authenticated
  using (public.is_household_member(household_id))
  with check (public.is_household_member(household_id));
create policy "household photos" on public.photos
  for all to authenticated
  using (public.is_household_member(household_id))
  with check (public.is_household_member(household_id));

-- ---------- Table privileges (least privilege; nothing for anon) ----------

revoke all on public.households, public.members, public.places, public.visits, public.photos from anon, authenticated;
grant select on public.households, public.members to authenticated;
grant update (display_name) on public.members to authenticated;
grant select, insert, update, delete on public.places, public.visits, public.photos to authenticated;

-- ---------- Creating and joining a household ----------
-- Households and members are only ever created through these two functions,
-- so nobody can add themselves to someone else's household directly.

create function public.create_household(p_display_name text)
returns public.households
language plpgsql
security definer
set search_path = ''
as $$
declare
  h public.households;
  c text;
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if exists (select 1 from public.members where user_id = auth.uid()) then
    raise exception 'You are already in a household';
  end if;

  loop
    -- 12 hex characters from a random UUID, shown as XXXX-XXXX-XXXX.
    c := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
    c := substr(c, 1, 4) || '-' || substr(c, 5, 4) || '-' || substr(c, 9, 4);
    begin
      insert into public.households (code) values (c) returning * into h;
      exit;
    exception when unique_violation then
      null; -- extremely unlikely; try another code
    end;
  end loop;

  insert into public.members (household_id, user_id, slot, display_name)
  values (h.id, auth.uid(), 1, btrim(p_display_name));
  return h;
end;
$$;

create function public.join_household(p_code text, p_display_name text)
returns public.households
language plpgsql
security definer
set search_path = ''
as $$
declare
  h public.households;
  taken smallint[];
  new_slot smallint;
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if exists (select 1 from public.members where user_id = auth.uid()) then
    raise exception 'You are already in a household';
  end if;

  select * into h from public.households
  where replace(code, '-', '') = replace(upper(btrim(p_code)), '-', '');
  if not found then
    raise exception 'That code was not found';
  end if;

  select coalesce(array_agg(slot), '{}') into taken from public.members where household_id = h.id;
  if array_length(taken, 1) >= 2 then
    raise exception 'That household already has two adults';
  end if;
  new_slot := case when 1 = any (taken) then 2 else 1 end;

  insert into public.members (household_id, user_id, slot, display_name)
  values (h.id, auth.uid(), new_slot, btrim(p_display_name));
  return h;
end;
$$;

revoke execute on function public.create_household(text), public.join_household(text, text) from public, anon;
grant execute on function public.create_household(text), public.join_household(text, text) to authenticated;

-- ---------- Photo storage ----------
-- Private bucket. Objects live under <household_id>/..., and only members of
-- that household can read, add or remove them.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('photos', 'photos', false, 5242880, array['image/jpeg']);

create policy "household members read photos" on storage.objects
  for select to authenticated
  using (bucket_id = 'photos' and public.is_household_member(((storage.foldername(name))[1])::uuid));
create policy "household members add photos" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'photos' and public.is_household_member(((storage.foldername(name))[1])::uuid));
create policy "household members remove photos" on storage.objects
  for delete to authenticated
  using (bucket_id = 'photos' and public.is_household_member(((storage.foldername(name))[1])::uuid));
